    throw new DownloadByRootError({
      code: DownloadByRootErrorCode.MISSING_BLOB_RESPONSE,
      blockRoot: prettyBytes(rootHex),
      peer: peerIdStr,
    });
  }
  for (const blobSidecar of blobSidecars) {
    if (blockInput.hasBlob(blobSidecar.index)) {
